class BatteryService {
  static const _channel = EventChannel('app/battery');
  StreamSubscription<dynamic>? _native;

  late final StreamController<int> _controller = StreamController<int>.broadcast(
    onListen: _start,     // first subscriber: turn the hardware on
    onCancel: _stop,      // last one leaves: turn it off
  );

  Stream<int> get level => _controller.stream;   // the only public surface

  void _start() {
    _native = _channel.receiveBroadcastStream().listen(
      (event) {
        if (!_controller.isClosed) _controller.add(event as int);
      },
      onError: (Object e, StackTrace s) => _controller.addError(e, s),
    );
  }

  void _stop() {
    _native?.cancel();
    _native = null;
  }

  Future<void> dispose() async {
    await _stop();
    await _controller.close();
  }
}

