class PriceFeed {
  final _out = StreamController<Quote>.broadcast();
  StreamSubscription<Quote>? _sub;
  int _attempt = 0;

  Stream<Quote> get quotes => _out.stream;   // survives every reconnect

  void connect() {
    final channel = IOWebSocketChannel.connect(
      Uri.parse('wss://api.example.com/quotes'),
      pingInterval: const Duration(seconds: 20),   // protocol-level liveness
    );

    _sub = channel.stream
        .map((raw) => Quote.fromJson(jsonDecode(raw as String) as Map<String, dynamic>))
        // 30s of silence becomes something the pipeline can react to
        .timeout(
          const Duration(seconds: 30),
          onTimeout: (sink) => sink.addError(const FeedStalled()),
        )
        .listen(
          (q) {
            _attempt = 0;
            _out.add(q);
          },
          onError: (Object e, StackTrace s) {
            _out.addError(e, s);
            _reconnect();          // timeout does NOT close the socket for you
          },
          onDone: _reconnect,
        );
  }

  void _reconnect() {
    _sub?.cancel();
    final backoff = 200 * (1 << _attempt.clamp(0, 6));
    _attempt++;
    Timer(
      Duration(milliseconds: backoff + Random().nextInt(250)),  // jitter
      connect,                     // a brand new channel; the old one is dead
    );
  }

  Future<void> dispose() async {
    await _sub?.cancel();
    await _out.close();
  }
}

