  Stream<Quote> get changes => _out.stream;    // "tell me when it moves"

  // Or skip the bookkeeping: a BehaviorSubject IS a stream with a current
  // value — `.value` reads it, and it replays to every new subscriber.

  Future<void> dispose() async {
    await _sub.cancel();
    await _out.close();
  }
}

