// ❌ never completes: nothing ever listened to _events
class Uploader {
  final _events = StreamController<Progress>();
  Stream<Progress> get events => _events.stream;

  Future<void> shutdown() async {
    await _events.close();     // hangs when `events` was never listened to
  }
}

// ✅ broadcast: done completes with or without listeners
class Uploader2 {
  final _events = StreamController<Progress>.broadcast();
  Stream<Progress> get events => _events.stream;

  void report(Progress p) {
    if (!_events.isClosed) _events.add(p);   // add-after-close throws
  }

  Future<void> shutdown() => _events.close();
}

// ✅ single-subscription controller inside a State: fire and forget
@override
void dispose() {
  unawaited(_controller.close());            // dart:async
  super.dispose();
}

// addStream locks the controller until its future completes
Future<void> pump(Stream<Progress> source) async {
  await _events.addStream(source);   // add/addError/close throw while pending
  await _events.close();
}

