import 'dart:convert';
import 'package:async/async.dart';

Future<Session> open(Socket socket) async {
  final lines = socket
      .cast<List<int>>()
      .transform(utf8.decoder)
      .transform(const LineSplitter());

  final queue = StreamQueue<String>(lines);   // takes the one subscription
  try {
    final hello = await queue.next;           // exactly one event, consumed
    if (!hello.startsWith('HELLO ')) {
      throw ProtocolException('unexpected greeting: $hello');
    }
    final version = int.parse(hello.substring(6));

    // Look ahead without committing: an optional banner only v2 servers send
    final probe = queue.startTransaction();
    final lookahead = probe.newQueue();
    final compressed = version >= 2 && await lookahead.next == 'GZIP';
    if (compressed) {
      probe.commit(lookahead);                // the banner is consumed
    } else {
      probe.reject();                         // nothing was consumed
    }

    // Hand the remainder over as an ordinary stream
    return Session(version, compressed, frames: queue.rest);
  } catch (_) {
    await queue.cancel(immediate: true);      // release the socket subscription
    rethrow;
  }
}

